@spec tm_trill_spec  src=tests/specs/tm_trill_spec.lua  loc=159  cases=4
@exercises trackerManager (h.tm), midiManager (h.fm), configManager (h.cm)
@surface   tm:addEvent, tm:flush, tm:getChannel, fm:dump, tm:rebuild, cm:set
@harness   mk

# Intent
  Note macros, v1: trill (structural, second kind). Trill alternates the host
  pitch with a note `cents` away from what it sounds, the remainder landing as
  per-fxNote detune -- which the absorber pass realises once the 4.9 gather
  unions derived lane-1 fxNotes. G4 runs microtonally under swing+delay:
  the frame/rounding AND detune/absorber round-trip tripwire.

# Helpers
  @fn cents2raw(c)  @ 18
      -- Matches tm's centsToRaw at the default pbRange (2 semitones = 200 cents).
  @fn fxNotesOf(dump, hostUuid)  @ 20-27
  @fn pbsByPpq(dump)  @ 29-36
  @fn fullView(dump)  @ 39-48
      -- Stable, order-independent view of notes + pbs for byte-identical assertions.

# Cases
  @case 'G4: flush -> rebuild -> flush byte-identical (trill, microtonal, swing + delay)'  [harness]  @ 55-83
  @case 'trill alternates host pitch with the stepped note; the host parks, all hits derived'  [harness]  @ 89-109
  @case 'a microtonal trill seats absorbers at the alternation fxNote seats'  [harness]  @ 115-133
  @case 'a temper change leaves the trill it renames sounding as it was'  [harness]  @ 139-156

# Uses (outbound edges)
  @use call tm:addEvent  @ 63,92,118,142
  @use call tm:flush  @ 65,80,94,120,144,154
  @use call tm:getChannel  @ 69,97,146
  @use call fm:dump  @ 71,76,78,81,96,126,147,152,155
  @use call tm:rebuild  @ 79
  @use call cm:set  @ 153

